def resolve_primary_tf(conn, symbol) -> tuple[str, list[str]]:
    """返回 (primary_tf, degraded)。1d 历史不足 WARMUP_BARS 则降级 4h。"""
    from regime.classify import WARMUP_BARS      # 280，复用，不新造
    d1 = storage.get_ohlcv(conn, symbol, "1d", limit=1200)
    if len(d1) < WARMUP_BARS:
        return "4h", ["primary_downgraded_1d"]
