def struct_bias(struct: dict) -> dict:
    """纯 §1 结构轴读数（影子，绝不进动作层）。
    pivot_dir 就是 structure_direction()：最近 3 对同类枢轴的 HH/HL(+1) vs LH/LL(-1)。"""
    pd_ = struct.get("pivot_dir")
    if pd_ is None: return {"bias": None, "strength": None}
    return {
        "bias": "HH/HL" if pd_ > 0 else ("LH/LL" if pd_ < 0 else "平行"),
        "strength": abs(pd_),        # 0..1
        "disagrees_with_host": None,  # 由调用方填：host==range 且 |pivot_dir|>=0.5
        "basis": "policy_§1_structure_axis_shadow",   # 展示层必须打这个标
    }

def evaluate(ctx):
  if not ctx.bar_closed: return ABSTAIN('未收线不作确认依据')
  if ctx.policy_regime is None or ctx.location is None: base=ABSTAIN('上游层缺失')
  # 1 否决层预扫（三态；None 记 UNRESOLVED 并按保守方向当已触发处理）
  vetoes=[v for v in VETOES if v.fire(ctx) is not False]
  block_open = any(v.scope in (BLOCK_ALL,BLOCK_OPEN) for v in vetoes if v.fired)
  # 2 §5 先跑，且不受 BLOCK_OPEN 影响
  manage = eval_manage(ctx) if ctx.position.side!='flat' else []
  # 3 §2.5：breakout_alert 的 RISK_CHECK 是风控动作不是入场
  if ctx.policy_regime=='breakout_alert': manage.insert(0, risk_check(ctx))
  # 4 开仓路径
  prop=None; rows=match_matrix(ctx); hit=top_priority_unique(rows)
  if hit is AMBIGUOUS: return ABSTAIN('矩阵多行同优先级命中', rows)
  if not block_open and hit and hit.action.startswith('OPEN'):
      prop=build_proposal(ctx,hit)
      gates=run_gates(ctx,prop)            # 全跑，不短路
      if any(g.status!=PASS for g in gates): prop=None; wait_kind=WAIT_GATE
      else: prop=apply_modifier_vetoes(ctx,prop,vetoes); prop.route=lock_route(hit,ctx)
  # 5 shadow 模式吞掉开仓
  if ctx.engine_mode=='shadow' and prop: return D(WAIT, WAIT_CALIBRATION, shadow_proposal=prop, manage=manage)
  return assemble(manage, prop, vetoes, gates, rows, ctx)

