def move_stop(conn, pos_id, new_stop, *, reason, ts, known_at, src='manual'):
    p = get_position(conn, pos_id)
    if p['stop'] is not None:
        if p['side']=='long'  and new_stop < p['stop']: raise StopWidenRejected(...)
        if p['side']=='short' and new_stop > p['stop']: raise StopWidenRejected(...)
    # 已被穿越的"移动"其实是"已止损"：long 且 new_stop >= 最新已收线 close → 拒绝，提示改走 CLOSE
    if not reason: raise ValueError('止损变更必须写理由')
    append_event(kind='STOP_MOVE', stop_from=p['stop'], stop_to=new_stop, ...)

