CREATE TRIGGER IF NOT EXISTS trg_stop_monotonic
BEFORE UPDATE OF stop ON position FOR EACH ROW
WHEN NEW.stop IS NOT NULL AND OLD.stop IS NOT NULL
 AND ((OLD.side='long' AND NEW.stop < OLD.stop) OR (OLD.side='short' AND NEW.stop > OLD.stop))
BEGIN SELECT RAISE(ABORT,'止损只能收紧不能放宽（policy §5 / P03）'); END;
CREATE TRIGGER IF NOT EXISTS trg_route_locked
BEFORE UPDATE OF route ON position FOR EACH ROW
WHEN OLD.route IS NOT NULL AND NEW.route <> OLD.route
BEGIN SELECT RAISE(ABORT,'退出路线开仓即锁定，不可混用（P03）'); END;
CREATE TRIGGER IF NOT EXISTS trg_budget_frozen
BEFORE UPDATE OF budget_total ON position_building FOR EACH ROW
WHEN OLD.status='active' AND NEW.budget_total <> OLD.budget_total
BEGIN SELECT RAISE(ABORT,'建仓总预算固定，加预算=一把梭（P21/§6.8）'); END;

